// One item per customer message. Accepts one message (JSON object), a JSON
// list or {"messages": [...]}, {"csv": "..."}, or a CSV file / text/csv body.
// Column names are the same as the Inbox Triage CSV import.
const FIELDS = {
  received_at: ['received_at', 'date', 'created_at', 'timestamp', 'received', 'datetime', 'sent_at'],
  source: ['source', 'channel', 'via', 'origin'],
  from: ['from', 'sender', 'customer', 'contact'],
  email: ['email', 'customer_email', 'from_email'],
  name: ['name', 'customer_name', 'from_name'],
  subject: ['subject', 'title'],
  message: ['message', 'body', 'content', 'text', 'description'],
  external_id: ['id', 'external_id', 'ticket_id', 'reference'],
};

// CSV with quoted fields, commas and line breaks inside quotes, CRLF, BOM.
function parseCsv(text) {
  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  const src = text.replace(/^﻿/, '');
  for (let i = 0; i < src.length; i++) {
    const c = src[i];
    if (inQuotes) {
      if (c === '"' && src[i + 1] === '"') { field += '"'; i++; }
      else if (c === '"') inQuotes = false;
      else field += c;
    } else if (c === '"') inQuotes = true;
    else if (c === ',') { row.push(field); field = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && src[i + 1] === '\n') i++;
      row.push(field); field = '';
      if (row.some((v) => v !== '')) rows.push(row);
      row = [];
    } else field += c;
  }
  row.push(field);
  if (row.some((v) => v !== '')) rows.push(row);
  if (rows.length < 2) return [];
  const header = rows[0].map((h) => h.trim().toLowerCase());
  return rows.slice(1).map((r) => Object.fromEntries(header.map((h, i) => [h, (r[i] ?? '').trim()])));
}

function fromText(text) {
  const t = String(text ?? '').trim();
  if (!t) return [];
  if (t.startsWith('{') || t.startsWith('[')) {
    try { return fromValue(JSON.parse(t)); } catch (err) { /* not JSON: read it as CSV */ }
  }
  return parseCsv(t);
}

function fromValue(value) {
  if (Array.isArray(value)) return value;
  if (typeof value === 'string') return fromText(value);
  if (!value || typeof value !== 'object') return [];
  if (Array.isArray(value.messages)) return value.messages;
  if (typeof value.csv === 'string') return parseCsv(value.csv);
  return Object.keys(value).length ? [value] : [];
}

function normalize(record) {
  if (!record || typeof record !== 'object' || Array.isArray(record)) return {};
  const lower = Object.fromEntries(Object.entries(record).map(([k, v]) => [k.trim().toLowerCase(), v]));
  // Email tools often send the sender as { name, address }.
  if (lower.from && typeof lower.from === 'object') {
    lower.name = lower.name ?? lower.from.name;
    lower.email = lower.email ?? lower.from.email ?? lower.from.address;
    delete lower.from;
  }
  const out = {};
  for (const [field, names] of Object.entries(FIELDS)) {
    const hit = names.find((n) => lower[n] !== undefined && lower[n] !== null && typeof lower[n] !== 'object' && String(lower[n]).trim() !== '');
    if (hit) out[field] = String(lower[hit]).trim();
  }
  return out;
}

const input = $input.first();
let records = fromValue(input.json.body);
// A CSV file or a text/csv body arrives as binary data.
if (!records.length) {
  for (const key of Object.keys(input.binary ?? {})) {
    const buffer = await this.helpers.getBinaryDataBuffer(0, key);
    records = fromText(buffer.toString('utf8'));
    if (records.length) break;
  }
}
if (!records.length) {
  return [{ json: { error: 'No message found. Send one message as JSON, a JSON list, {"messages": [...]}, {"csv": "..."} or a CSV file with a header line.' } }];
}
return records.map((r) => ({ json: normalize(r) }));

// One answer for the caller: created, already known (duplicate), rejected
// (e.g. empty text) or failed (wrong token, tool unreachable), row by row.
const results = $input.all().map((item, i) => {
  const status = item.json.statusCode ?? null;
  const body = item.json.body && typeof item.json.body === 'object' ? item.json.body : {};
  const outcome = status === 201 ? 'created'
    : status === 200 && body.status === 'duplicate' ? 'duplicate'
      : status === 422 ? 'rejected' : 'failed';
  const problem = body.error ?? item.json.error?.message ?? item.json.error ?? item.json.statusMessage ?? 'No answer from Inbox Triage';
  return {
    row: i + 1,
    outcome,
    status,
    conversationId: body.conversationId ?? null,
    team: body.analysis?.team ?? null,
    urgency: body.analysis?.urgency ?? null,
    error: outcome === 'created' || outcome === 'duplicate' ? null : String(problem),
  };
});
const count = (outcome) => results.filter((r) => r.outcome === outcome).length;
return [{ json: { received: results.length, created: count('created'), duplicate: count('duplicate'), rejected: count('rejected'), failed: count('failed'), results } }];
